package com.ccb.testmanagement.defect;

// 关键逻辑：所有读写以认证用户的租户、测试大类和项目为共同边界；写入由事务与审计保持一致性。

import com.ccb.attachment.integration.AttachmentBindingCommand;
import com.ccb.attachment.integration.AttachmentGateway;
import com.ccb.attachment.integration.AttachmentItem;
import com.ccb.common.api.PageQuery;
import com.ccb.common.api.PageResult;
import com.ccb.common.exception.BusinessException;
import com.ccb.common.exception.ErrorCode;
import com.ccb.security.model.AuthUser;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.*;
import java.util.concurrent.atomic.AtomicLong;

/** 测试缺陷：编号恒定、平级关联执行记录、状态流转及完整轨迹。 */
@Service
public class TestDefectService {
    public static final String BUSINESS_TYPE="TEST_DEFECT";
    private static final Set<String> DOMAINS=Set.of("application-assembly","user-testing","non-functional","security"), STATUS=Set.of("RAISED","CAUSE_IDENTIFIED","FIX_PLAN_CONFIRMED","PENDING_VERIFICATION","RESOLVED"), CATEGORY=Set.of("FUNCTION","DATA","UI","PERFORMANCE","SECURITY","ENVIRONMENT","REQUIREMENT","OPERATION","OTHER"), LEVEL=Set.of("FATAL","SERIOUS","GENERAL","MINOR"), TRI=Set.of("HIGH","MEDIUM","LOW");
    private static final AtomicLong IDS=new AtomicLong(System.currentTimeMillis()*1000);
    private final JdbcTemplate jdbc; private final AttachmentGateway attachments; private final ObjectMapper mapper;
    public TestDefectService(JdbcTemplate jdbc,AttachmentGateway attachments,ObjectMapper mapper){this.jdbc=jdbc;this.attachments=attachments;this.mapper=mapper;}

    public Map<String,Object> tree(String d,long p,AuthUser u){project(d,p,u);long t=u.tenantId();return Map.of(
            "systems",jdbc.queryForList("SELECT s.physical_subsystem_id id,a.code,a.short_name,COALESCE(NULLIF(a.short_name,''),REPLACE(a.name,'物理子系统','')) name FROM tm_test_participating_system s JOIN arch_physical_subsystem a ON a.id=s.physical_subsystem_id AND a.tenant_id=s.tenant_id AND a.deleted=0 WHERE s.tenant_id=? AND s.test_domain=? AND s.project_id=? AND s.enabled=1 AND s.deleted=0 ORDER BY a.code",t,d,p),
            "rounds",jdbc.queryForList("SELECT id,round_code,round_name,sort_no FROM tm_test_round WHERE tenant_id=? AND test_domain=? AND project_id=? AND deleted=0 ORDER BY sort_no,id",t,d,p),
            "cycles",jdbc.queryForList("SELECT c.id,c.round_id,c.cycle_code,c.cycle_name,c.sort_no FROM tm_test_cycle c JOIN tm_test_round r ON r.id=c.round_id AND r.tenant_id=c.tenant_id AND r.deleted=0 WHERE c.tenant_id=? AND r.test_domain=? AND r.project_id=? AND c.deleted=0 ORDER BY c.sort_no,c.id",t,d,p),
            "environments",jdbc.queryForList("SELECT id,env_code,env_name FROM tm_test_environment WHERE tenant_id=? AND enabled=1 AND deleted=0 ORDER BY sort_no,id",t),
            "handlers",jdbc.queryForList("SELECT DISTINCT r.physical_subsystem_id,u.id,u.display_name,u.username FROM tm_test_system_role r JOIN sys_user u ON u.id=r.user_id AND u.tenant_id=r.tenant_id AND u.deleted=0 WHERE r.tenant_id=? AND r.test_domain=? AND r.project_id=? AND r.role_code='DEVELOPER' AND r.deleted=0 ORDER BY u.display_name,u.id",t,d,p));}
    public PageResult<Map<String,Object>> list(String d,long p,Long system,String keyword,Collection<String> statuses,Collection<String> category,Collection<String> severity,Collection<String> priority,Collection<String> urgency,Long handler,Long proposer,String link,boolean recycle,String quick,String sortBy,String sortOrder,PageQuery page,AuthUser u){project(d,p,u);StringBuilder w=new StringBuilder(" WHERE f.tenant_id=? AND f.test_domain=? AND f.project_id=? AND ").append(recycle?"f.deleted=1 AND f.deleted_at>=DATE_SUB(CURRENT_TIMESTAMP,INTERVAL 30 DAY)":"f.deleted=0");List<Object>a=new ArrayList<>(List.of(u.tenantId(),d,p));if(system!=null){system(d,p,system,u.tenantId());w.append(" AND f.physical_subsystem_id=?");a.add(system);}String q=text(keyword,200,"关键字");if(q!=null){w.append(" AND (f.defect_code LIKE ? OR f.summary LIKE ?)");a.add("%"+q+"%");a.add("%"+q+"%");}in(w,a,"f.status",statuses,STATUS,"状态");in(w,a,"f.defect_category",category,CATEGORY,"缺陷分类");in(w,a,"f.severity",severity,LEVEL,"严重程度");in(w,a,"f.priority",priority,TRI,"优先级");in(w,a,"f.urgency",urgency,TRI,"紧急程度");if(handler!=null){w.append(" AND f.handler_id=?");a.add(handler);}if(proposer!=null){w.append(" AND f.proposer_id=?");a.add(proposer);}String quickFilter=text(quick,16,"快捷筛选");if(quickFilter!=null){switch(quickFilter.toUpperCase(Locale.ROOT)){case "SUBMITTED"-> {w.append(" AND f.proposer_id=?");a.add(u.id());}case "HANDLED"-> {w.append(" AND f.handler_id=? AND f.status<>'RESOLVED'");a.add(u.id());}case "VERIFY"-> {w.append(" AND f.proposer_id=? AND f.status='PENDING_VERIFICATION'");a.add(u.id());}default->throw bad("快捷筛选无效");}}if("LINKED".equalsIgnoreCase(link))w.append(" AND EXISTS(SELECT 1 FROM tm_test_defect_execution x WHERE x.tenant_id=f.tenant_id AND x.defect_id=f.id AND x.relation_state='ACTIVE')");if("UNLINKED".equalsIgnoreCase(link))w.append(" AND NOT EXISTS(SELECT 1 FROM tm_test_defect_execution x WHERE x.tenant_id=f.tenant_id AND x.defect_id=f.id AND x.relation_state='ACTIVE')");String from=" FROM tm_test_defect f JOIN arch_physical_subsystem s ON s.id=f.physical_subsystem_id AND s.tenant_id=f.tenant_id LEFT JOIN sys_user h ON h.id=f.handler_id AND h.tenant_id=f.tenant_id AND h.deleted=0 LEFT JOIN sys_user qy ON qy.id=f.proposer_id AND qy.tenant_id=f.tenant_id AND qy.deleted=0";Long total=jdbc.queryForObject("SELECT COUNT(*)"+from+w,Long.class,a.toArray());Map<String,String> orders=Map.of("defect_code","f.defect_code","summary","f.summary","status","f.status","proposed_at","f.proposed_at","updated_at","f.updated_at");String order=orders.getOrDefault(sortBy==null?"":sortBy,"f.proposed_at")+("ascending".equalsIgnoreCase(sortOrder)?" ASC":" DESC")+",f.id DESC";List<Object>b=new ArrayList<>(a);b.add((page.page()-1)*page.size());b.add(page.size());String sql="SELECT f.*,s.code physical_system_code,COALESCE(NULLIF(s.short_name,''),REPLACE(s.name,'物理子系统','')) physical_system_name,h.display_name handler_name,qy.display_name proposer_name,(SELECT COUNT(*) FROM tm_test_defect_execution x WHERE x.tenant_id=f.tenant_id AND x.defect_id=f.id AND x.relation_state='ACTIVE') execution_count"+from+w+" ORDER BY "+order+" LIMIT ?,?";return new PageResult<>(jdbc.queryForList(sql,b.toArray()),total==null?0:total,page.page(),page.size());}
    public List<Map<String,Object>> exportRows(String d,long p,Long system,String keyword,Collection<String> statuses,Collection<String> category,Collection<String> severity,Collection<String> priority,Collection<String> urgency,AuthUser u){return list(d,p,system,keyword,statuses,category,severity,priority,urgency,null,null,null,false,null,"proposed_at","descending",new PageQuery(1,2000),u).records();}
    @Transactional public Map<String,Object> create(String d,long p,Map<String,Object>b,AuthUser u){project(d,p,u);long system=positive(b.get("physical_subsystem_id"),"所属系统");system(d,p,system,u.tenantId());String summary=required(b.get("summary"),"概述",100), description=requiredHtml(b.get("description_html"),"缺陷描述");String category=value(b.get("defect_category"),CATEGORY,"缺陷分类"),severity=value(b.get("severity"),LEVEL,"严重程度"),priority=value(b.get("priority"),TRI,"优先级"),urgency=value(b.get("urgency"),TRI,"紧急程度");Long round=nullable(b.get("round_id")),cycle=nullable(b.get("cycle_id")),handler=nullable(b.get("handler_id"));if(handler!=null)handler(d,p,system,handler,u.tenantId());Map<String,Object> sys=jdbc.queryForMap("SELECT code FROM arch_physical_subsystem WHERE id=? AND tenant_id=? AND deleted=0",system,u.tenantId());int serial=nextSerial(system,u.tenantId());long id=next();String code="BUG"+sys.get("code")+"-"+String.format("%04d",serial);jdbc.update("INSERT INTO tm_test_defect(id,tenant_id,test_domain,project_id,physical_subsystem_id,defect_code,defect_serial_no,summary,description_html,round_id,cycle_id,defect_category,severity,priority,urgency,found_version,test_environment_code,handler_id,proposer_id,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,u.tenantId(),d,p,system,code,serial,summary,description,round,cycle,category,severity,priority,urgency,text(b.get("found_version"),50,"发现版本"),text(b.get("test_environment_code"),64,"测试环境"),handler,u.id(),u.id(),u.id());associate(id,ids(b.get("execution_ids")),d,p,u);syncAttachments(id,b.get("attachment_ids"),u);trace(id,d,p,"CREATE",u,Map.of("defect_code",code));return detail(d,p,id,u);}
    @Transactional public Map<String,Object> update(String d,long p,long id,Map<String,Object>b,AuthUser u){Map<String,Object> old=row(id,d,p,u.tenantId());long system=b.containsKey("physical_subsystem_id")?positive(b.get("physical_subsystem_id"),"所属系统"):number(old.get("physical_subsystem_id"));system(d,p,system,u.tenantId());String summary=b.containsKey("summary")?required(b.get("summary"),"概述",100):String.valueOf(old.get("summary"));String description=b.containsKey("description_html")?requiredHtml(b.get("description_html"),"缺陷描述"):String.valueOf(old.get("description_html"));String category=b.containsKey("defect_category")?value(b.get("defect_category"),CATEGORY,"缺陷分类"):String.valueOf(old.get("defect_category"));String severity=b.containsKey("severity")?value(b.get("severity"),LEVEL,"严重程度"):String.valueOf(old.get("severity")),priority=b.containsKey("priority")?value(b.get("priority"),TRI,"优先级"):String.valueOf(old.get("priority")),urgency=b.containsKey("urgency")?value(b.get("urgency"),TRI,"紧急程度"):String.valueOf(old.get("urgency"));Long handler=b.containsKey("handler_id")?nullable(b.get("handler_id")):nullable(old.get("handler_id"));if(handler!=null)handler(d,p,system,handler,u.tenantId());jdbc.update("UPDATE tm_test_defect SET physical_subsystem_id=?,summary=?,description_html=?,round_id=?,cycle_id=?,defect_category=?,severity=?,priority=?,urgency=?,found_version=?,test_environment_code=?,handler_id=?,updated_by=? WHERE id=? AND tenant_id=?",system,summary,description,b.containsKey("round_id")?nullable(b.get("round_id")):nullable(old.get("round_id")),b.containsKey("cycle_id")?nullable(b.get("cycle_id")):nullable(old.get("cycle_id")),category,severity,priority,urgency,b.containsKey("found_version")?text(b.get("found_version"),50,"发现版本"):old.get("found_version"),b.containsKey("test_environment_code")?text(b.get("test_environment_code"),64,"测试环境"):old.get("test_environment_code"),handler,u.id(),id,u.tenantId());if(b.containsKey("attachment_ids"))syncAttachments(id,b.get("attachment_ids"),u);trace(id,d,p,"UPDATE",u,Map.of("summary",summary));return detail(d,p,id,u);}
    public Map<String,Object> detail(String d,long p,long id,AuthUser u){Map<String,Object> out=new LinkedHashMap<>(row(id,d,p,u.tenantId()));out.put("executions",jdbc.queryForList("SELECT x.id relation_id,x.execution_id,x.relation_state,x.snapshot_case_code,x.snapshot_case_name,x.snapshot_scope_code,x.snapshot_scope_name,e.execution_status,c.case_code,c.case_name,s.scope_code,s.scope_name FROM tm_test_defect_execution x LEFT JOIN tm_test_execution e ON e.id=x.execution_id AND e.tenant_id=x.tenant_id AND e.deleted=0 LEFT JOIN tm_test_case c ON c.id=e.case_id AND c.tenant_id=e.tenant_id LEFT JOIN tm_test_scope s ON s.id=c.scope_id AND s.tenant_id=c.tenant_id WHERE x.tenant_id=? AND x.defect_id=? ORDER BY x.created_at DESC",u.tenantId(),id));out.put("traces",jdbc.queryForList("SELECT t.*,u.display_name operator_name FROM tm_test_defect_trace t LEFT JOIN sys_user u ON u.id=t.operator_id AND u.tenant_id=t.tenant_id AND u.deleted=0 WHERE t.tenant_id=? AND t.defect_id=? ORDER BY t.created_at DESC,t.id DESC",u.tenantId(),id));out.put("attachments",attachmentRows(id,u.tenantId()));return out;}
    @Transactional public Map<String,Object> transition(String d,long p,long id,String target,AuthUser u){Map<String,Object> f=row(id,d,p,u.tenantId());String to=value(target,STATUS,"目标状态"),from=String.valueOf(f.get("status"));if(!allowed(from,to))throw bad("当前缺陷状态不允许该流转");transitionAllowed(d,p,f,to,u);jdbc.update("UPDATE tm_test_defect SET status=?,updated_by=? WHERE id=? AND tenant_id=?",to,u.id(),id,u.tenantId());trace(id,d,p,"TRANSITION",u,Map.of("from",from,"to",to));return detail(d,p,id,u);}
    @Transactional public void associate(long defectId,Collection<Long> executionIds,String d,long p,AuthUser u){if(executionIds.isEmpty())return;row(defectId,d,p,u.tenantId());for(long execution:executionIds){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_execution WHERE id=? AND tenant_id=? AND test_domain=? AND project_id=? AND deleted=0",Long.class,execution,u.tenantId(),d,p);if(n==null||n==0)throw bad("执行记录不存在或不属于当前项目");Long x=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_defect_execution WHERE tenant_id=? AND defect_id=? AND execution_id=? AND relation_state='ACTIVE'",Long.class,u.tenantId(),defectId,execution);if(x==null||x==0)jdbc.update("INSERT INTO tm_test_defect_execution(id,tenant_id,defect_id,execution_id,relation_state,created_by,updated_by) VALUES(?,?,?,?,?,?,?)",next(),u.tenantId(),defectId,execution,"ACTIVE",u.id(),u.id());}trace(defectId,d,p,"ASSOCIATE_EXECUTION",u,Map.of("execution_ids",executionIds));}
    @Transactional public void detach(long defectId,long execution,String d,long p,AuthUser u){Map<String,Object> e=jdbc.queryForMap("SELECT c.case_code,c.case_name,s.scope_code,s.scope_name FROM tm_test_execution x JOIN tm_test_case c ON c.id=x.case_id AND c.tenant_id=x.tenant_id JOIN tm_test_scope s ON s.id=c.scope_id AND s.tenant_id=c.tenant_id WHERE x.id=? AND x.tenant_id=?",execution,u.tenantId());int changed=jdbc.update("UPDATE tm_test_defect_execution SET execution_id=NULL,relation_state='SNAPSHOT',snapshot_case_code=?,snapshot_case_name=?,snapshot_scope_code=?,snapshot_scope_name=?,updated_by=? WHERE tenant_id=? AND defect_id=? AND execution_id=? AND relation_state='ACTIVE'",e.get("case_code"),e.get("case_name"),e.get("scope_code"),e.get("scope_name"),u.id(),u.tenantId(),defectId,execution);if(changed==0)throw bad("缺陷关联不存在");trace(defectId,d,p,"DETACH_EXECUTION",u,Map.of("execution_id",execution));}
    @Transactional public void remove(String d,long p,long id,AuthUser u){row(id,d,p,u.tenantId());Long links=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_defect_execution WHERE tenant_id=? AND defect_id=? AND relation_state='ACTIVE'",Long.class,u.tenantId(),id);if(links!=null&&links>0)throw bad("存在关联执行记录的缺陷不可删除");jdbc.update("UPDATE tm_test_defect SET deleted=1,deleted_at=CURRENT_TIMESTAMP,deleted_by=?,updated_by=? WHERE id=? AND tenant_id=?",u.id(),u.id(),id,u.tenantId());trace(id,d,p,"DELETE",u,Map.of());}
    @Transactional public void restore(String d,long p,long id,AuthUser u){project(d,p,u);List<Map<String,Object>> rows=jdbc.queryForList("SELECT id FROM tm_test_defect WHERE id=? AND tenant_id=? AND test_domain=? AND project_id=? AND deleted=1 AND deleted_at>=DATE_SUB(CURRENT_TIMESTAMP,INTERVAL 30 DAY)",id,u.tenantId(),d,p);if(rows.isEmpty())throw bad("缺陷不存在或已超过30天恢复期限");jdbc.update("UPDATE tm_test_defect SET deleted=0,deleted_at=NULL,deleted_by=NULL,updated_by=? WHERE id=? AND tenant_id=?",u.id(),id,u.tenantId());trace(id,d,p,"RESTORE",u,Map.of());}
    private void syncAttachments(long defectId,Object raw,AuthUser u){Set<Long>wanted=new LinkedHashSet<>(ids(raw));for(Map<String,Object> item:attachmentRows(defectId,u.tenantId())){long attachmentId=number(item.get("id"));if(!wanted.contains(attachmentId)){attachments.deleteBound(attachmentId,BUSINESS_TYPE,String.valueOf(defectId),u);jdbc.update("UPDATE tm_test_defect_attachment SET deleted=1,deleted_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND defect_id=? AND attachment_id=?",u.tenantId(),defectId,attachmentId);}}int sort=0;for(long attachmentId:wanted){AttachmentItem item=attachments.get(attachmentId,u);if(item.fileSize()>50L*1024*1024)throw bad("单个附件不能超过50MB");Long exists=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_defect_attachment WHERE tenant_id=? AND defect_id=? AND attachment_id=? AND deleted=0",Long.class,u.tenantId(),defectId,attachmentId);if(exists==null||exists==0){attachments.bind(new AttachmentBindingCommand(attachmentId,BUSINESS_TYPE,String.valueOf(defectId),null),u);jdbc.update("INSERT INTO tm_test_defect_attachment(id,tenant_id,defect_id,attachment_id,sort_no,created_by) VALUES(?,?,?,?,?,?)",next(),u.tenantId(),defectId,attachmentId,sort,u.id());}sort++;}}
    private List<Map<String,Object>> attachmentRows(long defectId,long tenantId){return jdbc.queryForList("SELECT a.attachment_id id,f.file_name,f.file_size,f.content_type,a.sort_no FROM tm_test_defect_attachment a LEFT JOIN att_file f ON f.id=a.attachment_id AND f.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.defect_id=? AND a.deleted=0 ORDER BY a.sort_no,a.id",tenantId,defectId);}
    private Map<String,Object> row(long id,String d,long p,long t){List<Map<String,Object>>r=jdbc.queryForList("SELECT f.*,s.code physical_system_code,COALESCE(NULLIF(s.short_name,''),REPLACE(s.name,'物理子系统','')) physical_system_name,h.display_name handler_name,q.display_name proposer_name FROM tm_test_defect f JOIN arch_physical_subsystem s ON s.id=f.physical_subsystem_id AND s.tenant_id=f.tenant_id LEFT JOIN sys_user h ON h.id=f.handler_id AND h.tenant_id=f.tenant_id AND h.deleted=0 LEFT JOIN sys_user q ON q.id=f.proposer_id AND q.tenant_id=f.tenant_id AND q.deleted=0 WHERE f.id=? AND f.tenant_id=? AND f.test_domain=? AND f.project_id=? AND f.deleted=0",id,t,d,p);if(r.isEmpty())throw bad("缺陷不存在或不属于当前项目");return r.get(0);}private void project(String d,long p,AuthUser u){if(!DOMAINS.contains(d))throw bad("测试大类无效");Long n=jdbc.queryForObject("SELECT COUNT(*) FROM pm_project WHERE id=? AND tenant_id=? AND deleted=0",Long.class,p,u.tenantId());if(n==null||n==0)throw bad("项目不存在或无权访问");}private void system(String d,long p,long s,long t){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_participating_system WHERE tenant_id=? AND test_domain=? AND project_id=? AND physical_subsystem_id=? AND enabled=1 AND deleted=0",Long.class,t,d,p,s);if(n==null||n==0)throw bad("请选择已启用的参测系统");}private void handler(String d,long p,long s,long id,long t){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_system_role WHERE tenant_id=? AND test_domain=? AND project_id=? AND physical_subsystem_id=? AND user_id=? AND role_code='DEVELOPER' AND deleted=0",Long.class,t,d,p,s,id);if(n==null||n==0)throw bad("处理人必须是所属系统的开发人员");}private boolean role(String d,long p,long s,long user,String code,long t){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_system_role WHERE tenant_id=? AND test_domain=? AND project_id=? AND physical_subsystem_id=? AND user_id=? AND role_code=? AND deleted=0",Long.class,t,d,p,s,user,code);return n!=null&&n>0;}private void transitionAllowed(String d,long p,Map<String,Object> f,String to,AuthUser u){long system=number(f.get("physical_subsystem_id"));boolean manager=role(d,p,system,u.id(),"TEST_MANAGER",u.tenantId()), developer=Objects.equals(nullable(f.get("handler_id")),u.id()), proposer=number(f.get("proposer_id"))==u.id(), elevated=authority("test-management:"+d+":defects:delete");if(elevated)return;if(Set.of("CAUSE_IDENTIFIED","FIX_PLAN_CONFIRMED","PENDING_VERIFICATION").contains(to)&&(developer||manager))return;if(Set.of("RESOLVED","RAISED").contains(to)&&(proposer||manager))return;throw new BusinessException(ErrorCode.FORBIDDEN,"无权执行当前缺陷状态流转");}private boolean authority(String value){var auth=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();return auth!=null&&auth.getAuthorities().stream().anyMatch(a->value.equals(a.getAuthority()));}private int nextSerial(long system,long tenant){Integer n=jdbc.queryForObject("SELECT COALESCE(MAX(defect_serial_no),0)+1 FROM tm_test_defect WHERE tenant_id=? AND physical_subsystem_id=?",Integer.class,tenant,system);return n==null?1:n;}private void trace(long id,String d,long p,String action,AuthUser u,Map<String,Object>data){try{jdbc.update("INSERT INTO tm_test_defect_trace(id,tenant_id,test_domain,project_id,defect_id,action_code,operator_id,detail_json) VALUES(?,?,?,?,?,?,?,?)",next(),u.tenantId(),d,p,id,action,u.id(),mapper.writeValueAsString(data));}catch(Exception e){throw new BusinessException(ErrorCode.INTERNAL_ERROR,"缺陷轨迹写入失败");}}private static boolean allowed(String from,String to){return switch(from){case "RAISED"->to.equals("CAUSE_IDENTIFIED");case "CAUSE_IDENTIFIED"->to.equals("FIX_PLAN_CONFIRMED");case "FIX_PLAN_CONFIRMED"->to.equals("PENDING_VERIFICATION");case "PENDING_VERIFICATION"->to.equals("RESOLVED")||to.equals("RAISED");case "RESOLVED"->to.equals("RAISED");default->false;};}private static void in(StringBuilder w,List<Object>a,String col,Collection<String>raw,Set<String>allowed,String label){List<String>x=new ArrayList<>();if(raw!=null)for(String v:raw)x.add(value(v,allowed,label));if(!x.isEmpty()){w.append(" AND ").append(col).append(" IN (").append(String.join(",",Collections.nCopies(x.size(),"?"))).append(")");a.addAll(x);}}private static String value(Object x,Set<String>allowed,String label){String s=required(x,label,64).toUpperCase(Locale.ROOT);if(!allowed.contains(s))throw bad(label+"无效");return s;}private static String requiredHtml(Object x,String label){String s=required(x,label,200000).replaceAll("(?is)<script[^>]*>.*?</script>","");if(s.replaceAll("<[^>]*>","").trim().isEmpty())throw bad(label+"不能为空");return s;}private static String required(Object x,String label,int max){String s=text(x,max,label);if(s==null)throw bad(label+"不能为空");return s;}private static String text(Object x,int max,String label){if(x==null)return null;String s=String.valueOf(x).trim();if(s.isEmpty()||"null".equals(s))return null;if(s.length()>max)throw bad(label+"不能超过"+max+"个字符");return s;}private static long positive(Object x,String label){Long n=nullable(x);if(n==null||n<=0)throw bad(label+"无效");return n;}private static Long nullable(Object x){if(x==null||String.valueOf(x).isBlank()||"null".equals(String.valueOf(x)))return null;try{return Long.parseLong(String.valueOf(x));}catch(Exception e){throw bad("编号无效");}}private static long number(Object x){return ((Number)x).longValue();}private static List<Long> ids(Object x){List<Long>out=new ArrayList<>();if(x instanceof Collection<?>c)for(Object v:c)out.add(positive(v,"编号"));return out;}private static long next(){return IDS.incrementAndGet();}private static BusinessException bad(String m){return new BusinessException(ErrorCode.BAD_REQUEST,m);}
}
